package main
import("context";"encoding/json";"fmt";"os";"github.com/jackc/pgx/v5/pgxpool")
func main(){c:=context.Background();p,e:=pgxpool.New(c,os.Getenv("DATABASE_URL"));if e!=nil{panic(e)};defer p.Close();rows,e:=p.Query(c,`SELECT jsonb_build_object('id',r.id,'stream_id',r.stream_id,'next_fire',r.next_fire_at,'capture_via',r.capture_via,'binding_equal',r.stream_url=s.source_url,'revision',(SELECT max(id) FROM stream_source_revisions WHERE stream_id=s.id),'checks',coalesce((SELECT jsonb_agg(jsonb_build_object('stage',p.stage,'result',p.result,'method',p.method,'checked',p.checked_at,'attempts',p.attempt_count,'detail',p.detail) ORDER BY p.checked_at) FROM recording_preopen_checks p WHERE p.recording_id=r.id AND p.window_start_at=r.next_fire_at),'[]'),'canary',coalesce((SELECT jsonb_agg(jsonb_build_object('stage',e.stage,'node',e.node_id,'duration_ms',e.duration_ms,'bytes',e.size_bytes,'codec',e.video_codec,'relay_version',e.relay_version,'source_revision',e.source_revision,'completed',e.completed_at) ORDER BY e.completed_at) FROM recording_canary_preopen_evidence e WHERE e.recording_id=r.id AND e.window_start_at=r.next_fire_at),'[]')) FROM recordings r JOIN streams s ON s.id=r.stream_id WHERE r.account_id=47 AND r.status='active' AND r.mode='continuous' ORDER BY r.next_fire_at,r.id`);if e!=nil{panic(e)};defer rows.Close();for rows.Next(){var b []byte;_ = rows.Scan(&b);var x any;_ = json.Unmarshal(b,&x);o,_:=json.Marshal(x);fmt.Println(string(o))}}
